use sea_orm_migration::prelude::*;

mod config;
mod models;

use config::database::DatabaseConfig;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!(" 데이터베이스 생성 테스트를 시작합니다...");

    // 데이터베이스 연결
    let db = DatabaseConfig::connect().await?;
    println!("✅ 데이터베이스 연결 성공!");

    // 마이그레이션 실행
    println!(" 마이그레이션을 실행합니다...");
    migration::Migrator::up(&db, None).await?;
    println!("✅ 마이그레이션 완료!");

    // 파일 존재 확인
    if std::path::Path::new("./data/app.db").exists() {
        let metadata = std::fs::metadata("./data/app.db")?;
        println!("✅ app.db 파일이 생성되었습니다! (크기: {} bytes)", metadata.len());
    } else {
        println!("❌ app.db 파일이 생성되지 않았습니다.");
    }

    println!(" 테스트 완료!");
    Ok(())
}

use sea_orm::{Database, DatabaseConnection, DbErr};
use std::fs;
use std::path::Path;

pub struct DatabaseConfig;

impl DatabaseConfig {
    pub async fn connect() -> Result<DatabaseConnection, DbErr> {
        // 현재 작업 디렉토리 확인
        let current_dir = std::env::current_dir()
            .map_err(|e| DbErr::Custom(format!("현재 디렉토리 확인 실패: {}", e)))?;
        println!("현재 작업 디렉토리: {:?}", current_dir);

        // src 디렉토리 기준으로 data 폴더 경로 설정
        let data_dir = "./src/data";
        if !Path::new(data_dir).exists() {
            println!("data 디렉토리 생성: {}", data_dir);
            fs::create_dir_all(data_dir)
                .map_err(|e| DbErr::Custom(format!("폴더 생성 실패: {}", e)))?;
        }

        let database_url = "sqlite:./src/data/app.db?mode=rwc";
        println!("데이터베이스 연결 시도: {}", database_url);

        match Database::connect(database_url).await {
            Ok(connection) => {
                println!("✅ 데이터베이스 연결 성공!");
                // 데이터베이스 파일 존재 확인
                if Path::new("./src/data/app.db").exists() {
                    println!("✅ app.db 파일이 생성되었습니다!");
                } else {
                    println!("⚠️ app.db 파일이 아직 생성되지 않았습니다.");
                }
                Ok(connection)
            }
            Err(e) => {
                eprintln!("❌ 데이터베이스 연결 실패: {:?}", e);
                Err(e)
            }
        }
    }
}

