use sea_orm::DatabaseConnection;
use std::sync::OnceLock;

static DB_CONNECTION: OnceLock<DatabaseConnection> = OnceLock::new();

pub struct Database;

impl Database {
    // 데이터베이스 연결 초기화
    pub fn initialize(connection: DatabaseConnection) {
        DB_CONNECTION.set(connection).expect("Database connection already initialized");
    }

    // 데이터베이스 연결 가져오기
    pub fn get() -> &'static DatabaseConnection {
        DB_CONNECTION.get().expect("Database connection not initialized")
    }
}

use actix_web::{web, HttpResponse, Result};
use crate::services::main_service::MainService;

pub struct MainController;

impl MainController {
    pub async fn hello() -> Result<HttpResponse> {
        let message = MainService::get_hello_message().await;
        Ok(HttpResponse::Ok().json(serde_json::json!({
            "message": message
        })))
    }
}

pub fn configure(cfg: &mut web::ServiceConfig) {
    cfg.service(
        web::scope("/api")
            .route("/hello", web::get().to(MainController::hello))
    );
}

