use sea_orm::entity::prelude::*;
use sea_orm::{Set, ActiveModelTrait};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

#[derive(Clone, Debug, PartialEq, DeriveEntityModel, Eq, Serialize, Deserialize)]
#[sea_orm(table_name = "file")]
pub struct Model {
    #[sea_orm(primary_key, auto_increment = false)]
    pub saved_file_name: String,
    pub original_file_name: String,
    pub file_size: i64,
    pub status: String,
    pub created_at: chrono::DateTime<chrono::Utc>,
    pub updated_at: chrono::DateTime<chrono::Utc>,
}

#[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]
pub enum Relation {}

impl ActiveModelBehavior for ActiveModel {
    fn new() -> Self {
        Self {
            saved_file_name: Set(Uuid::now_v7().to_string()),
            original_file_name: Set(String::new()),
            file_size: Set(0),
            status: Set("pending".to_string()),
            created_at: Set(chrono::Utc::now()),
            updated_at: Set(chrono::Utc::now()),
        }
    }
}

impl Model {
    /// 새로운 파일 모델 생성 (UUID v7 자동 생성)
    pub fn new_with_uuid(
        original_file_name: String,
        file_size: i64,
        status: String,
    ) -> ActiveModel {
        ActiveModel {
            saved_file_name: Set(Uuid::now_v7().to_string()),
            original_file_name: Set(original_file_name),
            file_size: Set(file_size),
            status: Set(status),
            created_at: Set(chrono::Utc::now()),
            updated_at: Set(chrono::Utc::now()),
        }
    }

    /// UUID v7 값 검증 함수
    pub fn validate_uuid_v7(&self) -> bool {
        match Uuid::parse_str(&self.saved_file_name) {
            Ok(uuid) => {
                // UUID v7 버전 확인 (version 7)
                uuid.get_version() == Some(uuid::Version::SortRand)
            }
            Err(_) => false,
        }
    }

    /// 새로운 UUID v7 생성 및 반환
    pub fn generate_uuid_v7() -> String {
        Uuid::now_v7().to_string()
    }
}

